examples.template:
MonarchPostCard(
    {{title}},
    author: {{author}},
    excerpt: {{excerpt}},
    publishedAt: {{publishedAt|date}},
    now: {{now|date}},
    tags: [MonarchPostCardTag({{tags.0.label}}), MonarchPostCardTag({{tags.1.label}})],
    isAnswered: {{answered}},
    reactionCount: {{reactionCount}},
    commentCount: {{commentCount}}
) {
    opened = true
}

examples.code:
MonarchPostCard("Welcome to the community", author: "Ben Okafor", isPinned: true, commentCount: 2) {
    // Open the post.
} actions: {
    Toggle("Save", systemImage: "bookmark", isOn: $isSaved)
        .toggleStyle(.monarchButton(.ghost, size: .sm))
        .labelStyle(.iconOnly)
}
